typedef struct nodo {
  int dato;
  struct nodo *sig;
} TNodo;

TNodo *crearNodo(int dato) {
  TNodo *nuevo = malloc(sizeof(TNodo));

  if (nuevo == NULL) {
    return NULL;
  }
  nuevo->dato = dato;
  nuevo->sig = NULL;
  return nuevo;
}

void insertarFinal(TNodo **lista, int dato) {
  TNodo *nuevo = crearNodo(dato);
  TNodo *aux;

  if (nuevo == NULL) {
    return;
  }
  if (*lista == NULL) {
    *lista = nuevo;
    return;
  }
  aux = *lista;
  while (aux->sig != NULL) {
    aux = aux->sig;
  }
  aux->sig = nuevo;
}

void liberarLista(TNodo **lista) {
  TNodo *aux;

  while (*lista != NULL) {
    aux = *lista;
    *lista = aux->sig;
    free(aux);
  }
}

consignas.despues:
int main() {
  TNodo *lista = NULL;
  int n;
  int dato;
  int cantidad;

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &dato);
    insertarFinal(&lista, dato);
  }
  cantidad = contar(lista);
  printf("%d", cantidad);
  liberarLista(&lista);
  return 0;
}

